"""
NVIDIA Parakeet ASR (NeMo FastConformer + CTC/RNN-T/TDT).

Catalog models:
  - parakeet-tdt-ctc-0.6b-ja  (Japanese Hybrid TDT-CTC)
  - parakeet-tdt-0.6b-v2      (English TDT; punct/caps/timestamps)
  - parakeet-tdt-0.6b-v3      (25 EU languages; auto-detect)

Long media is windowed to keep VRAM bounded.

JA Hybrid TDT-CTC was trained with max_duration≈30s — keep JA windows ≤30s.
EN/EU TDT v2/v3 tolerate longer clips; still chunk for VRAM and cue density.

NeMo Hypothesis.timestamp is a dict with keys word/segment/char (and an
internal timestep index list). Prefer word stamps for subtitle packing.
"""

from __future__ import annotations

import logging
import re
import shutil
import tempfile
import threading
from pathlib import Path
from typing import Any, Callable

from ..download import is_model_installed, model_local_path
from ..models_catalog import get_spec
from ..progress import asr_local_from_timeline, format_mmss

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.parakeet")

_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()

# JA Hybrid train config uses max_duration=30; longer windows mash many lines
# into one Hypothesis segment and destroy subtitle timing (seen on ADN-798).
_WINDOW_S_JA = 30.0
_WINDOW_S_DEFAULT = 60.0
_OVERLAP_S = 0.75
_TARGET_CUE_CHARS = 28
_MAX_CUE_S = 12.0
_GAP_BREAK_S = 0.4
_SENTENCE_END = set("。！？!?．.｡…")
_SENTENCE_SPLIT_RE = re.compile(r"(?<=[。！？!?．.｡…])")


def clear_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _resolve_device(device: str) -> str:
    d = str(device or "auto").strip().lower()
    if d == "cpu":
        return "cpu"
    try:
        import torch

        if torch.cuda.is_available() and d in ("auto", "cuda"):
            return "cuda"
    except Exception:
        pass
    return "cpu"


def _find_nemo_file(model_dir: Path) -> Path | None:
    nemo_files = sorted(model_dir.glob("*.nemo"))
    for p in nemo_files:
        try:
            if p.is_file() and p.stat().st_size > 1024:
                return p
        except OSError:
            continue
    return None


def _window_s_for(asr_model: str) -> float:
    mid = str(asr_model or "").strip().lower()
    if "ja" in mid or "tdt-ctc" in mid or "tdt_ctc" in mid:
        return _WINDOW_S_JA
    return _WINDOW_S_DEFAULT


def _get_asr_model(model_dir: Path, hub_id: str, device: str) -> Any:
    import torch
    import nemo.collections.asr as nemo_asr

    map_device = _resolve_device(device)
    key = f"{model_dir}|{map_device}"
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached

        model = None
        nemo_path = _find_nemo_file(model_dir)
        load_errors: list[str] = []

        # Always restore on CPU first — CUDA DLL path may be injected only after
        # engine startup; map_location="cuda" can fail with CPU-only torch wheels.
        if nemo_path is not None:
            try:
                model = nemo_asr.models.ASRModel.restore_from(
                    restore_path=str(nemo_path),
                    map_location="cpu",
                )
            except Exception as err:
                load_errors.append(f"restore_from({nemo_path.name}): {err}")
                _log.warning("Parakeet restore_from failed: %s", err)

        if model is None:
            for candidate in (str(model_dir), str(hub_id or "").strip()):
                if not candidate:
                    continue
                try:
                    model = nemo_asr.models.ASRModel.from_pretrained(
                        model_name=candidate
                    )
                    break
                except Exception as err:
                    load_errors.append(f"from_pretrained({candidate}): {err}")
                    _log.warning("Parakeet from_pretrained(%s) failed: %s", candidate, err)

        if model is None:
            detail = "; ".join(load_errors[-3:]) or "unknown"
            raise RuntimeError(
                f"Failed to load Parakeet under {model_dir}. "
                f"Re-download the model, then retry. Last errors: {detail}"
            )

        model.eval()
        if map_device == "cuda":
            try:
                model = model.cuda()
                _log.info("Parakeet moved to CUDA (%s)", torch.cuda.get_device_name(0))
            except Exception as err:
                _log.warning("Parakeet CUDA move failed (%s); staying on CPU", err)
                map_device = "cpu"
                key = f"{model_dir}|cpu"
        else:
            try:
                model = model.cpu()
            except Exception:
                pass

        _MODEL_CACHE[key] = model
        return model


def _probe_duration_s(media_path: str) -> float:
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _windows(duration_s: float, window_s: float) -> list[tuple[float, float]]:
    win = max(8.0, float(window_s))
    if duration_s <= win + 1.0:
        return [(0.0, max(duration_s, 0.1))]
    out: list[tuple[float, float]] = []
    cursor = 0.0
    step = max(5.0, win - _OVERLAP_S)
    while cursor < duration_s - 0.05:
        end = min(duration_s, cursor + win)
        out.append((cursor, end))
        if end >= duration_s - 0.05:
            break
        cursor += step
    return out or [(0.0, max(duration_s, 0.1))]


def _is_cjk(text: str) -> bool:
    return any("\u3040" <= c <= "\u30ff" or "\u4e00" <= c <= "\u9fff" for c in text)


def _join_tokens(parts: list[str]) -> str:
    if not parts:
        return ""
    if any(_is_cjk(p) for p in parts):
        return "".join(parts)
    return " ".join(parts)


def _stamp_text(st: dict[str, Any]) -> str:
    for key in ("segment", "word", "text"):
        v = st.get(key)
        if isinstance(v, (list, tuple)):
            v = "".join(str(x) for x in v)
        text = str(v or "").strip()
        if text:
            return text
    v = st.get("char")
    if isinstance(v, (list, tuple)):
        return "".join(str(x) for x in v).strip()
    return str(v or "").strip()


def _stamp_list(raw: Any, *, prefer: str = "word") -> list[dict[str, Any]]:
    if raw is None:
        return []
    if isinstance(raw, dict):
        # Skip the internal index list under "timestep".
        order = (
            ("word", "segment", "char")
            if prefer == "word"
            else ("segment", "word", "char")
        )
        for key in order:
            nested = raw.get(key)
            if nested:
                return _stamp_list(nested, prefer=prefer)
        return []
    if not isinstance(raw, (list, tuple)):
        return []
    out: list[dict[str, Any]] = []
    for item in raw:
        if isinstance(item, dict):
            text = _stamp_text(item)
            if not text:
                continue
            try:
                start = float(item.get("start") or 0)
                end = float(item.get("end") if item.get("end") is not None else start)
            except (TypeError, ValueError):
                continue
            out.append({"start": start, "end": max(end, start), "text": text})
            continue
        text = str(
            getattr(item, "segment", None)
            or getattr(item, "word", None)
            or getattr(item, "char", None)
            or getattr(item, "text", None)
            or ""
        ).strip()
        start = getattr(item, "start", None)
        end = getattr(item, "end", None)
        if text and start is not None:
            try:
                s = float(start)
                e = float(end) if end is not None else s
            except (TypeError, ValueError):
                continue
            out.append({"start": s, "end": max(e, s), "text": text})
    return out


def _hyp_text(hyp: Any) -> str:
    if hyp is None:
        return ""
    if isinstance(hyp, str):
        return hyp.strip()
    text = getattr(hyp, "text", None)
    if text is not None:
        return str(text).strip()
    if isinstance(hyp, dict):
        return str(hyp.get("text") or "").strip()
    return str(hyp).strip()


def _hyp_timestamps(hyp: Any) -> Any:
    if hyp is None:
        return None
    for attr in ("timestamp", "timestep"):
        ts = getattr(hyp, attr, None)
        if isinstance(ts, dict) and any(k in ts for k in ("word", "segment", "char")):
            return ts
        if ts is not None and not isinstance(ts, dict):
            return ts
    if isinstance(hyp, dict):
        return hyp.get("timestamp") or hyp.get("timestep")
    return None


def _split_sentences(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [p.strip() for p in _SENTENCE_SPLIT_RE.split(raw) if p and p.strip()]
    if len(parts) <= 1 and len(raw) > _TARGET_CUE_CHARS * 2:
        # No punctuation — hard-wrap by char budget for CJK walls of text.
        chunk = _TARGET_CUE_CHARS
        parts = [raw[i : i + chunk].strip() for i in range(0, len(raw), chunk)]
        parts = [p for p in parts if p]
    return parts or [raw]


def _distribute_text_cues(
    text: str,
    *,
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    """Split a text blob across [start, end] by sentence / length."""
    parts = _split_sentences(text)
    if not parts:
        return []
    span = max(0.35, float(end) - float(start))
    weights = [max(1, len(p)) for p in parts]
    total_w = float(sum(weights))
    cues: list[dict[str, Any]] = []
    cursor = float(start)
    for i, (part, w) in enumerate(zip(parts, weights)):
        frac = w / total_w
        dur = span * frac
        if i == len(parts) - 1:
            cue_end = float(end)
        else:
            cue_end = min(float(end), cursor + max(0.35, dur))
        cue_end = max(cue_end, cursor + 0.25)
        cues.append({"start": cursor, "end": min(cue_end, cursor + _MAX_CUE_S * 2), "text": part})
        cursor = cue_end
    return cues


def _pack_word_cues(
    items: list[tuple[float, float, str]],
) -> list[dict[str, Any]]:
    if not items:
        return []
    cues: list[dict[str, Any]] = []
    buf: list[str] = []
    buf_start = items[0][0]
    prev_end = items[0][1]
    for start, end, text in items:
        gap = start - prev_end
        flush = False
        if buf and gap >= _GAP_BREAK_S:
            flush = True
        joined = _join_tokens(buf)
        if buf and len(joined) >= _TARGET_CUE_CHARS:
            flush = True
        if buf and joined and joined[-1] in _SENTENCE_END:
            flush = True
        if flush:
            cues.append(
                {
                    "start": buf_start,
                    "end": max(prev_end, buf_start + 0.25),
                    "text": joined.strip(),
                }
            )
            buf = []
            buf_start = start
        buf.append(text)
        prev_end = max(prev_end, end)
    if buf:
        cues.append(
            {
                "start": buf_start,
                "end": max(prev_end, buf_start + 0.25),
                "text": _join_tokens(buf).strip(),
            }
        )
    return [c for c in cues if str(c.get("text") or "").strip()]


def _items_to_cues(
    stamps: list[dict[str, Any]],
    *,
    offset_s: float,
    span_s: float,
) -> list[dict[str, Any]]:
    items: list[tuple[float, float, str]] = []
    for st in stamps:
        text = str(st.get("text") or _stamp_text(st) or "").strip()
        if not text:
            continue
        try:
            start = float(st.get("start") or 0)
            end = float(st.get("end") if st.get("end") is not None else start)
        except (TypeError, ValueError):
            continue
        # Drop zero-width / garbage tokens.
        if end < start:
            end = start
        items.append((start + offset_s, end + offset_s, text))
    if not items:
        return []

    avg_len = sum(len(t) for _, _, t in items) / max(1, len(items))
    # Word-level (short tokens) → pack; long segment blobs → sentence-split
    # across the stamp's real time range (do NOT clamp to 8s).
    if avg_len < 8 and len(items) >= 4:
        return _pack_word_cues(items)

    cues: list[dict[str, Any]] = []
    for start, end, text in items:
        if end <= start + 0.05:
            end = start + min(_MAX_CUE_S, max(0.5, span_s * 0.5))
        if len(text) <= _TARGET_CUE_CHARS and end - start <= _MAX_CUE_S:
            cues.append({"start": start, "end": max(end, start + 0.25), "text": text})
        else:
            cues.extend(_distribute_text_cues(text, start=start, end=max(end, start + 0.5)))
    return cues


def _result_to_cues(hyp: Any, *, offset_s: float, span_s: float) -> list[dict[str, Any]]:
    ts = _hyp_timestamps(hyp)
    # Prefer word stamps so soft-AV dialogue is not one mega-segment per window.
    stamps = _stamp_list(ts, prefer="word")
    if not stamps:
        stamps = _stamp_list(ts, prefer="segment")
    if stamps:
        cues = _items_to_cues(stamps, offset_s=offset_s, span_s=span_s)
        if cues:
            return cues
    text = _hyp_text(hyp)
    if not text:
        return []
    return _distribute_text_cues(
        text,
        start=offset_s,
        end=offset_s + max(0.5, float(span_s) * 0.95),
    )


def _transcribe_window(model: Any, wav_path: str) -> Any:
    """Call NeMo transcribe with timestamps when supported."""
    try:
        results = model.transcribe([wav_path], timestamps=True)
    except TypeError:
        results = model.transcribe([wav_path])
    except Exception:
        results = model.transcribe([wav_path])
    if isinstance(results, tuple) and results:
        results = results[0]
    if isinstance(results, list) and results:
        return results[0]
    return results


def parakeet_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "parakeet-tdt-0.6b-v2",
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models

    _ = language  # NeMo Parakeet TDT auto-detects / is monolingual per checkpoint.
    ensure_extras_for_models([asr_model], force=False, on_progress=on_progress)
    if not is_model_installed(asr_model):
        raise RuntimeError(
            f"ASR model not installed: {asr_model}. Download a Parakeet pack first."
        )
    asr_dir = model_local_path(asr_model)
    spec = get_spec(asr_model)
    hub_id = str(getattr(spec, "hub_id", "") or "")
    window_s = _window_s_for(asr_model)

    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": f"加载 Parakeet（{asr_model} · {int(window_s)}s 窗）…",
            }
        )
    model = _get_asr_model(asr_dir, hub_id, device)
    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），Parakeet 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )
    windows = _windows(duration_s, window_s)

    from ..audio.preprocess import trim_media_window

    work = Path(tempfile.mkdtemp(prefix="parakeet_"))
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    try:
        for i, (start, end) in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                detail = f"{format_mmss(start)} / {format_mmss(duration_s)} · Parakeet"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s,
                    }
                )
            try:
                wav = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i:04d}",
                )
                hyp = _transcribe_window(model, str(wav))
            except Exception as err:
                fail_count += 1
                _log.warning("Parakeet window %s-%s failed: %s", start, end, err)
                continue
            part = _result_to_cues(hyp, offset_s=start, span_s=max(0.1, end - start))
            for cue in part:
                if on_cue:
                    on_cue(cue)
                all_cues.append(cue)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    n_win = max(1, len(windows))
    if fail_count and (fail_count >= (n_win + 1) // 2 or not all_cues):
        raise RuntimeError(
            f"Parakeet failed {fail_count}/{n_win} windows "
            f"({Path(media_path).name}); aborting partial transcript"
        )

    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        item = dict(cue)
        # Keep real timestamp ends; only nudge overlaps.
        if cleaned and float(item["start"]) < float(cleaned[-1]["end"]) - 0.05:
            item["start"] = float(cleaned[-1]["end"])
            if float(item["end"]) <= float(item["start"]):
                item["end"] = float(item["start"]) + 0.25
        cleaned.append(item)

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（Parakeet · {int(window_s)}s 窗）",
                "processedSec": duration_s,
                "mediaDurationSec": duration_s,
            }
        )
    return cleaned
